def transform(grid):
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    mid = (r0 + r1) // 2
    counts = {}
    for r, c in cells:
        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    inner = max(counts, key=counts.get)
    border = next(k for k in counts if k != inner)
    out = [[bg] * w for _ in range(h)]
    for r, c in cells:
        if r == r0:
            nc = c + (c1 - c0 - 1)
        elif r <= mid:
            nc = c + (c1 - c0 - 3)
        else:
            nc = c
        out[r][nc] = border if grid[r][c] == inner else inner
    return out
